 622	    /// Initialize the subprocess. This will NOT start it, this only sets
 623	    /// up the internal state necessary to start it later.
 624	    pub fn init(gpa: Allocator, cfg: Config) !Subprocess {
 625	        // We have a lot of maybe-allocations that all share the same lifetime
 626	        // so use an arena so we don't end up in an accounting nightmare.
 627	        var arena = std.heap.ArenaAllocator.init(gpa);
 628	        errdefer arena.deinit();
 629	        const alloc = arena.allocator();
 630	
 631	        // Get our env. If a default env isn't provided by the caller
 632	        // then we get it ourselves.
 633	        var env = cfg.env;
 634	        errdefer env.deinit();
 635	
 636	        // If we have a resources dir then set our env var
 637	        if (cfg.resources_dir) |dir| {
 638	            log.info("found Ghostty resources dir: {s}", .{dir});
 639	            try env.put("GHOSTTY_RESOURCES_DIR", dir);
 640	        }
 641	
 642	        // Set our TERM var. This is a bit complicated because we want to use
 643	        // the ghostty TERM value but we want to only do that if we have
 644	        // ghostty in the TERMINFO database.
 645	        //
 646	        // For now, we just look up a bundled dir but in the future we should
 647	        // also load the terminfo database and look for it.
 830	        const args: []const [:0]const u8 = execCommand(
 831	            alloc,
 832	            shell_command,
 833	            internal_os.passwd,
 834	        ) catch |err| switch (err) {
 835	            // If we fail to allocate space for the command we want to
 836	            // execute, we'd still like to try to run something so
 837	            // Ghostty can launch (and maybe the user can debug this further).
 838	            // Realistically, if you're getting OOM, I think other stuff is
 839	            // about to crash, but we can try.
 840	            error.OutOfMemory => oom: {
 841	                log.warn("failed to allocate space for command args, falling back to basic shell", .{});
 842	
 843	                // The comptime here is important to ensure the full slice
 844	                // is put into the binary data and not the stack.
 845	                break :oom comptime switch (builtin.target.os.tag) {
 846	                    .windows => &.{"cmd.exe"},
 847	                    else => &.{"/bin/sh"},
 848	                };
 849	            },
 850	
 851	            // This logs on its own, this is a bad error.
 852	            error.SystemError => return err,
 853	        };
 854	
 855	        // We have to copy the cwd because there is no guarantee that
 856	        // pointers in full_config remain valid.
 857	        const cwd: ?[:0]u8 = if (cfg.working_directory) |cwd|
 858	            try alloc.dupeSentinel(u8, cwd, 0)
 859	        else
 860	            null;
 861	
 862	        // Propagate the current working directory (CWD) to the shell, enabling
 863	        // the shell to display the current directory name rather than the
 864	        // resolved path for symbolic links. This is important and based
 865	        // on the same behavior in Konsole and Kitty (see the linked issues):
 866	        // https://bugs.kde.org/show_bug.cgi?id=242114
 867	        // https://github.com/kovidgoyal/kitty/issues/1595
 868	        // https://github.com/ghostty-org/ghostty/discussions/7769
 869	        if (cwd) |pwd| try env.put("PWD", pwd);
 870	
 871	        return .{
 872	            .arena = arena,
 873	            .env = env,
 874	            .cwd = cwd,
 875	            .args = args,
 876	
 877	            .rt_pre_exec_info = cfg.rt_pre_exec_info,
 878	            .rt_post_fork_info = cfg.rt_post_fork_info,
 879	
 880	            // Should be initialized with initTerminal call.
 881	            .grid_size = .{},
 882	            .screen_size = .{ .width = 1, .height = 1 },
 883	        };
 884	    }
